/* Custom CSS for Task Manager API Documentation */

/* Stripe-inspired color scheme */
:root {
  --primary-color: #635BFF;
  --primary-dark: #0A2540;
  --success-color: #00D924;
  --warning-color: #FFC043;
  --error-color: #DF1B41;
  --text-primary: #1A1F36;
  --text-secondary: #697386;
  --border-color: #E3E8EF;
  --background-light: #F6F9FC;
}

/* Code blocks styling */
pre {
  background: var(--primary-dark) !important;
  border-radius: 8px;
  padding: 20px;
  border: 1px solid rgba(255, 255, 255, 0.05);
  position: relative;
}

code {
  font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
  font-size: 14px;
  line-height: 1.6;
}

/* Inline code */
:not(pre) > code {
  background: var(--background-light);
  color: var(--primary-color);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
}

/* HTTP Method badges */
.http-method {
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  display: inline-block;
  margin-right: 8px;
}

.http-method-get {
  background: #0074E8;
  color: white;
}

.http-method-post {
  background: var(--success-color);
  color: white;
}

.http-method-put {
  background: var(--warning-color);
  color: var(--primary-dark);
}

.http-method-delete {
  background: var(--error-color);
  color: white;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border-color);
  margin: 20px 0;
}

th {
  background: var(--background-light);
  font-weight: 600;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 12px;
  text-align: left;
  color: var(--text-secondary);
}

td {
  padding: 12px;
  border-top: 1px solid var(--border-color);
  color: var(--text-primary);
}

tr:hover {
  background: rgba(99, 91, 255, 0.02);
}

/* Callout blocks */
.callout {
  border-radius: 8px;
  padding: 16px;
  margin: 20px 0;
  border-left: 4px solid;
}

.callout-info {
  background: #F0F7FF;
  border-color: #0074E8;
  color: var(--text-primary);
}

.callout-warning {
  background: #FFF9E6;
  border-color: var(--warning-color);
  color: var(--text-primary);
}

.callout-success {
  background: #E6FFF2;
  border-color: var(--success-color);
  color: var(--text-primary);
}

.callout-error {
  background: #FFE6E6;
  border-color: var(--error-color);
  color: var(--text-primary);
}

/* Copy button for code blocks */
.copy-code-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 4px;
  padding: 6px 12px;
  color: white;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s;
}

.copy-code-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* Sidebar styling */
.sidebar {
  border-right: 1px solid var(--border-color);
}

.sidebar-item {
  transition: background 0.2s;
  border-radius: 6px;
  margin: 2px 0;
}

.sidebar-item:hover {
  background: var(--background-light);
}

.sidebar-item.active {
  background: rgba(99, 91, 255, 0.1);
  color: var(--primary-color);
  font-weight: 500;
}

/* Links */
a {
  color: var(--primary-color);
  text-decoration: none;
  transition: opacity 0.2s;
}

a:hover {
  opacity: 0.8;
  text-decoration: underline;
}

/* Headers */
h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary);
  font-weight: 600;
  margin-top: 24px;
  margin-bottom: 12px;
}

h1 {
  font-size: 32px;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 12px;
}

h2 {
  font-size: 24px;
}

h3 {
  font-size: 20px;
}

/* Badges */
.badge {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  margin-left: 8px;
}

.badge-required {
  background: var(--error-color);
  color: white;
}

.badge-optional {
  background: var(--text-secondary);
  color: white;
}

.badge-admin {
  background: var(--warning-color);
  color: var(--primary-dark);
}

/* Responsive */
@media (max-width: 768px) {
  pre {
    padding: 12px;
    font-size: 12px;
  }

  table {
    font-size: 14px;
  }

  th, td {
    padding: 8px;
  }
}
